"""Small standard-library implementation of the template forms used by Taskfiles."""
import re


def _lookup(path, context):
    path = path.strip()
    if path.startswith("."):
        path = path[1:]
    if not path:
        return context
    value = context
    for part in path.split("."):
        if isinstance(value, dict):
            value = value.get(part, "")
        elif isinstance(value, (list, tuple)) and part.isdigit():
            i = int(part)
            value = value[i] if i < len(value) else ""
        else:
            return ""
    return value


def _truth(v):
    return not (v is None or v is False or v == 0 or v == "" or v == [] or v == {})


def _value(expr, ctx):
    expr = expr.strip()
    # Handle simple pipelines and the common slim-sprig functions.
    pipeline = [p.strip() for p in expr.split("|")]
    value = None
    for n, part in enumerate(pipeline):
        tokens = re.findall(r'''(?:"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|[^\s]+)''', part)
        if not tokens:
            continue
        fn = tokens[0]
        if n and len(tokens) == 1:
            args = [value]
        else:
            args = []
            for t in tokens[1:]:
                if len(t) >= 2 and t[0] == t[-1] and t[0] in "\"'":
                    args.append(t[1:-1])
                elif t.startswith(".") or t.startswith("$"):
                    args.append(_lookup(t.lstrip("$"), ctx))
                elif t.lower() in ("true", "false"):
                    args.append(t.lower() == "true")
                else:
                    try: args.append(int(t))
                    except ValueError: args.append(t)
            if n:
                args.append(value)
        if fn.startswith(".") or fn.startswith("$"):
            value = _lookup(fn.lstrip("$"), ctx)
        elif fn in ("quote", "squote"):
            value = ('"' if fn == 'quote' else "'") + str(args[0] if args else "") + ('"' if fn == 'quote' else "'")
        elif fn in ("upper", "lower", "trim", "title"):
            s = str(args[0] if args else "")
            value = {"upper":s.upper,"lower":s.lower,"trim":s.strip,"title":s.title}[fn]()
        elif fn == "default":
            value = args[-1] if args and _truth(args[-1]) else (args[0] if args else "")
        elif fn == "join":
            sep = str(args[0]) if args else ""
            seq = args[-1] if len(args) > 1 else []
            value = sep.join(map(str, seq)) if isinstance(seq, (list, tuple)) else str(seq)
        elif fn == "splitList":
            sep, s = (str(args[0]), str(args[1])) if len(args) > 1 else (" ", str(args[0]) if args else "")
            value = s.split(sep)
        elif fn == "list":
            value = args
        elif fn == "dict":
            value = dict(zip(map(str,args[::2]),args[1::2]))
        elif fn in ("eq", "ne", "gt", "ge", "lt", "le"):
            a, b = (args + [None,None])[:2]
            try: a, b = float(a), float(b)
            except (ValueError, TypeError): a, b = str(a), str(b)
            value = {"eq":a==b,"ne":a!=b,"gt":a>b,"ge":a>=b,"lt":a<b,"le":a<=b}[fn]
        elif fn == "not": value = not _truth(args[0] if args else None)
        elif fn == "and": value = all(_truth(x) for x in args)
        elif fn == "or": value = next((x for x in args if _truth(x)), args[-1] if args else "")
        else:
            value = _lookup(fn, ctx)
    return value


def render(template, context=None):
    """Render common Go text/template interpolation and conditional blocks."""
    ctx = context or {}
    s = str(template)
    # Basic if/else/end blocks; process innermost blocks first.
    pat = re.compile(r"{{\s*if\s+(.+?)\s*}}(.*?){{\s*end\s*}}", re.S)
    for _ in range(30):
        m = pat.search(s)
        if not m: break
        body = m.group(2)
        halves = re.split(r"{{\s*else\s*}}", body, maxsplit=1)
        replacement = halves[0] if _truth(_value(m.group(1),ctx)) else (halves[1] if len(halves)>1 else "")
        s = s[:m.start()] + replacement + s[m.end():]
    def sub(m):
        val = _value(m.group(1),ctx)
        if val is None: return ""
        if isinstance(val, bool): return str(val).lower()
        if isinstance(val, (list,dict)): return str(val)
        return str(val)
    return re.sub(r"{{\s*(.*?)\s*}}", sub, s)


def resolve_vars(variables, inherited=None, env=None):
    """Resolve simple static/ref Taskfile vars in declaration order."""
    result = dict(inherited or {})
    result.update(env or {})
    for key, raw in (variables or {}).items():
        if isinstance(raw, dict) and "ref" in raw:
            val = _lookup(str(raw["ref"]), result)
        elif isinstance(raw, dict) and "map" in raw:
            val = raw["map"]
        elif isinstance(raw, dict):
            val = raw.get("sh", "")
        else:
            val = raw
        if isinstance(val, str): val = render(val, result)
        result[key] = val
    return result

