"""A small standard-library YAML reader for ordinary Taskfiles."""
import re


def _split_flow(s):
    out=[]; start=0; depth=0; quote=None; esc=False
    for i,c in enumerate(s):
        if quote:
            if esc: esc=False
            elif c=='\\' and quote=='"': esc=True
            elif c==quote: quote=None
        elif c in "'\"": quote=c
        elif c in '[{(': depth+=1
        elif c in ']})': depth-=1
        elif c==',' and depth==0: out.append(s[start:i].strip()); start=i+1
    out.append(s[start:].strip())
    return [x for x in out if x]


def _colon(s):
    quote=None; depth=0; esc=False
    for i,c in enumerate(s):
        if quote:
            if esc: esc=False
            elif c=='\\' and quote=='"': esc=True
            elif c==quote: quote=None
        elif c in "'\"": quote=c
        elif c in '[{(': depth+=1
        elif c in ']})': depth-=1
        elif c==':' and depth==0 and (i+1==len(s) or s[i+1].isspace()): return i
    return -1


def scalar(value):
    s=str(value).strip()
    if not s: return ''
    if s[0:1] in ('"', "'") and s[-1:] == s[0]:
        if s[0]=='"':
            try: return bytes(s[1:-1], 'utf-8').decode('unicode_escape')
            except Exception: return s[1:-1]
        return s[1:-1].replace("''", "'")
    if s.startswith('[') and s.endswith(']'):
        return [scalar(x) for x in _split_flow(s[1:-1])]
    if s.startswith('{') and s.endswith('}'):
        result={}
        for item in _split_flow(s[1:-1]):
            i=_colon(item)
            if i<0: continue
            result[str(scalar(item[:i]))]=scalar(item[i+1:])
        return result
    if s in ('true','True','TRUE'): return True
    if s in ('false','False','FALSE'): return False
